const n=[{id:"endocrine-glands-001",topicId:"endocrine-glands",question:"Что такое железа согласно определению лекции?",options:["Лимфатический узел, фильтрующий лимфу","Орган из секреторных эпителиальных клеток, способный вырабатывать и выделять биологически активные вещества","Скопление нервных клеток вне ЦНС","Полый мышечный орган для накопления жидкости"],correctIndex:1,explanation:"Железа — орган, состоящий из секреторных эпителиальных клеток, способный вырабатывать и выделять биологически активные вещества.",difficulty:"easy",tags:["определения"]},{id:"endocrine-glands-002",topicId:"endocrine-glands",question:"Как называется воспаление железы?",options:["Нефрит","Артрит","Остит","Аденит"],correctIndex:3,explanation:"Воспаление железы — аденит.",difficulty:"easy",tags:["терминология"]},{id:"endocrine-glands-003",topicId:"endocrine-glands",question:"Чем эндокринные железы отличаются от экзокринных?",options:["Имеют выводные протоки и выделяют секрет на поверхность тела","Выделяют секрет только в полость кишечника","Не имеют выводных протоков и выделяют гормоны прямо в кровь","Не вырабатывают биологически активных веществ"],correctIndex:2,explanation:"Эндокринные железы (внутренней секреции) не имеют выводных протоков и выделяют гормоны прямо в кровь.",difficulty:"easy",tags:["классификация желёз"]},{id:"endocrine-glands-004",topicId:"endocrine-glands",question:"Какие железы приведены в лекции как пример экзокринных?",options:["Гипофиз и эпифиз","Слюнные и потовые","Щитовидная и паращитовидные","Надпочечники и тимус"],correctIndex:1,explanation:"Экзокринные железы (внешней секреции) имеют выводные протоки — например, слюнные и потовые.",difficulty:"easy",tags:["классификация желёз"]},{id:"endocrine-glands-005",topicId:"endocrine-glands",question:"Какая железа приведена в лекции как пример смешанной?",options:["Поджелудочная","Щитовидная","Потовая","Слюнная"],correctIndex:0,explanation:"Смешанные железы обладают обеими функциями, например поджелудочная железа.",difficulty:"easy",tags:["классификация желёз"]},{id:"endocrine-glands-006",topicId:"endocrine-glands",question:"Как ещё называют эндокринную систему?",options:["Лимфатическая","Вегетативная","Соматическая","Гуморальная"],correctIndex:3,explanation:"Эндокринная (гуморальная) система — система органов, вырабатывающих гормоны.",difficulty:"medium",tags:["эндокринная система"]},{id:"endocrine-glands-007",topicId:"endocrine-glands",question:"Какие структуры являются высшими центрами регуляции эндокринной системы?",options:["Щитовидная железа и надпочечники","Гипоталамус и гипофиз","Поджелудочная железа и печень","Эпифиз и тимус"],correctIndex:1,explanation:"Высшие центры регуляции эндокринной системы — гипоталамус и гипофиз.",difficulty:"medium",tags:["эндокринная система","регуляция"]},{id:"endocrine-glands-008",topicId:"endocrine-glands",question:"Что НЕ относится к основным функциям эндокринной системы по лекции?",options:["Поддержание гомеостаза","Проведение нервных импульсов к скелетным мышцам","Адаптация к стрессу","Регуляция обмена веществ"],correctIndex:1,explanation:"Функции эндокринной системы: регуляция обмена веществ, рост и развитие, репродуктивная функция, адаптация к стрессу, поддержание гомеостаза, иммунная регуляция.",difficulty:"medium",tags:["эндокринная система","функции"]},{id:"endocrine-glands-009",topicId:"endocrine-glands",question:"Где расположен гипофиз?",options:["Над верхними полюсами почек","В верхнем средостении за грудиной","У основания мозга в турецком седле клиновидной кости","На передней поверхности шеи впереди трахеи"],correctIndex:2,explanation:"Гипофиз расположен у основания мозга в турецком седле клиновидной кости и связан с гипоталамусом ножкой.",difficulty:"medium",tags:["гипофиз","анатомия"]},{id:"endocrine-glands-010",topicId:"endocrine-glands",question:"Из каких долей состоит гипофиз?",options:["Из передней, промежуточной и задней","Из коркового и мозгового слоя","Из правой и левой долей и перешейка","Из головки, тела и хвоста"],correctIndex:0,explanation:"Гипофиз состоит из передней доли (аденогипофиз), промежуточной доли и задней доли (нейрогипофиз).",difficulty:"medium",tags:["гипофиз","анатомия"]},{id:"endocrine-glands-011",topicId:"endocrine-glands",question:"Как называется передняя доля гипофиза?",options:["Эпифиз","Нейрогипофиз","Гипоталамус","Аденогипофиз"],correctIndex:3,explanation:"Передняя доля гипофиза — аденогипофиз, задняя — нейрогипофиз.",difficulty:"medium",tags:["гипофиз"]},{id:"endocrine-glands-012",topicId:"endocrine-glands",question:"Какой гормон относится к задней доле гипофиза?",options:["Тиреотропный гормон","Соматотропный гормон","Вазопрессин (АДГ)","Пролактин"],correctIndex:2,explanation:"Гормон задней доли гипофиза — вазопрессин (АДГ).",difficulty:"medium",tags:["гипофиз","гормоны"]},{id:"endocrine-glands-013",topicId:"endocrine-glands",question:"Какой гормон передней доли гипофиза стимулирует щитовидную железу?",options:["Лютеинизирующий гормон (ЛГ)","Адренокортикотропный гормон (АКТГ)","Тиреотропный гормон (ТТГ)","Вазопрессин"],correctIndex:2,explanation:"Тиреотропный гормон (ТТГ) передней доли гипофиза стимулирует щитовидную железу.",difficulty:"easy",tags:["гипофиз","гормоны"]},{id:"endocrine-glands-014",topicId:"endocrine-glands",question:"За что отвечает соматотропный гормон (СТГ)?",options:["За снижение кальция в крови","За выработку молока","За водно-солевой баланс","За рост"],correctIndex:3,explanation:"Соматотропный гормон (СТГ) передней доли гипофиза отвечает за рост.",difficulty:"easy",tags:["гипофиз","гормоны"]},{id:"endocrine-glands-015",topicId:"endocrine-glands",question:"Что развивается при недостатке соматотропного гормона?",options:["Акромегалия","Микседема","Гигантизм","Карликовость (гипофизарный нанизм)"],correctIndex:3,explanation:"Недостаток соматотропного гормона приводит к карликовости (гипофизарному нанизму).",difficulty:"medium",tags:["гипофиз","патология"]},{id:"endocrine-glands-016",topicId:"endocrine-glands",question:"Что развивается при избытке соматотропного гормона у взрослых?",options:["Кретинизм","Акромегалия","Гигантизм","Гипофизарный нанизм"],correctIndex:1,explanation:"Избыток СТГ у взрослых вызывает акромегалию — увеличение кистей, стоп, нижней челюсти; у детей — гигантизм.",difficulty:"medium",tags:["гипофиз","патология"]},{id:"endocrine-glands-017",topicId:"endocrine-glands",question:"Чем проявляется акромегалия?",options:["Бронзовой пигментацией кожи","Экзофтальмом и тремором","Увеличением кистей, стоп и нижней челюсти","Отёчностью и сонливостью"],correctIndex:2,explanation:"Акромегалия — увеличение кистей, стоп, нижней челюсти при избытке СТГ у взрослых.",difficulty:"medium",tags:["гипофиз","патология"]},{id:"endocrine-glands-018",topicId:"endocrine-glands",question:"Какое состояние возникает у ребёнка при избыточной выработке СТГ?",options:["Карликовость","Акромегалия","Гигантизм","Кретинизм"],correctIndex:2,explanation:"Избыток соматотропного гормона у детей приводит к гигантизму.",difficulty:"medium",tags:["гипофиз","патология"]},{id:"endocrine-glands-019",topicId:"endocrine-glands",question:"Где расположен эпифиз (шишковидное тело)?",options:["В промежуточном мозге","В верхнем средостении","В турецком седле","В продолговатом мозге"],correctIndex:0,explanation:"Эпифиз (шишковидное тело) расположен в промежуточном мозге.",difficulty:"medium",tags:["эпифиз"]},{id:"endocrine-glands-020",topicId:"endocrine-glands",question:"Какой гормон вырабатывает эпифиз?",options:["Кортизол","Паратгормон","Тироксин","Мелатонин"],correctIndex:3,explanation:"Эпифиз вырабатывает мелатонин.",difficulty:"easy",tags:["эпифиз","гормоны"]},{id:"endocrine-glands-021",topicId:"endocrine-glands",question:"Какую функцию выполняет эпифиз?",options:["Регулирует циркадные ритмы (сон–бодрствование)","Регулирует водно-солевой баланс","Снижает уровень кальция в крови","Обеспечивает созревание Т-лимфоцитов"],correctIndex:0,explanation:"Функции эпифиза: выработка мелатонина, регуляция циркадных ритмов, торможение преждевременного полового созревания, антиоксидантная и иммуномодулирующая роль.",difficulty:"medium",tags:["эпифиз","функции"]},{id:"endocrine-glands-022",topicId:"endocrine-glands",question:"Как эпифиз влияет на половое созревание?",options:["Вызывает гигантизм","Тормозит преждевременное половое созревание","Не влияет на половое созревание","Ускоряет половое созревание"],correctIndex:1,explanation:"Одна из функций эпифиза — торможение преждевременного полового созревания.",difficulty:"hard",tags:["эпифиз","функции"]},{id:"endocrine-glands-023",topicId:"endocrine-glands",question:"Где расположена щитовидная железа?",options:["На задней поверхности трахеи","На передней поверхности шеи, впереди трахеи","У основания мозга","В верхнем средостении за грудиной"],correctIndex:1,explanation:"Щитовидная железа расположена на передней поверхности шеи, впереди трахеи; состоит из двух долей и перешейка.",difficulty:"easy",tags:["щитовидная железа","анатомия"]},{id:"endocrine-glands-024",topicId:"endocrine-glands",question:"Из каких частей состоит щитовидная железа?",options:["Из коркового и мозгового слоя","Из передней и задней доли","Из трёх долей","Из двух долей и перешейка"],correctIndex:3,explanation:"Щитовидная железа состоит из двух долей и перешейка.",difficulty:"medium",tags:["щитовидная железа","анатомия"]},{id:"endocrine-glands-025",topicId:"endocrine-glands",question:"Какой гормон щитовидной железы снижает уровень кальция в крови?",options:["Тироксин","Паратгормон","Альдостерон","Кальцитонин"],correctIndex:3,explanation:"Кальцитонин щитовидной железы снижает уровень кальция в крови.",difficulty:"medium",tags:["щитовидная железа","гормоны"]},{id:"endocrine-glands-026",topicId:"endocrine-glands",question:"Какие гормоны щитовидной железы регулируют обмен веществ, рост и развитие?",options:["Тироксин (Т4) и трийодтиронин (Т3)","Адреналин и норадреналин","Кортизол и альдостерон","Инсулин и глюкагон"],correctIndex:0,explanation:"Тироксин (Т4) и трийодтиронин (Т3) регулируют обмен веществ, рост и развитие.",difficulty:"easy",tags:["щитовидная железа","гормоны"]},{id:"endocrine-glands-027",topicId:"endocrine-glands",question:"Какие анализы используют для диагностики функции щитовидной железы согласно лекции?",options:["ТТГ, свободный Т3 и свободный Т4","Гликированный гемоглобин","Онкомаркеры и ПАП-тест","Креатинин и мочевину"],correctIndex:0,explanation:"Для диагностики функции щитовидной железы определяют ТТГ, свободный Т3 и свободный Т4.",difficulty:"medium",tags:["щитовидная железа","диагностика"]},{id:"endocrine-glands-028",topicId:"endocrine-glands",question:"Какое вещество используется для заместительной терапии при гипотиреозе?",options:["Кортизол","Кальцитонин","Левотироксин","Мелатонин"],correctIndex:2,explanation:"Заместительная терапия — левотироксин (L-тироксин).",difficulty:"medium",tags:["щитовидная железа","лечение"]},{id:"endocrine-glands-029",topicId:"endocrine-glands",question:"Как называется недостаток гормонов щитовидной железы у детей?",options:["Кретинизм","Микседема","Базедова болезнь","Акромегалия"],correctIndex:0,explanation:"Гипотиреоз у детей — кретинизм: задержка умственного развития, низкий рост, грубые черты лица.",difficulty:"medium",tags:["щитовидная железа","патология"]},{id:"endocrine-glands-030",topicId:"endocrine-glands",question:"Как называется гипотиреоз, развившийся у взрослого человека?",options:["Болезнь Аддисона","Кретинизм","Микседема","Болезнь Грейвса"],correctIndex:2,explanation:"Гипотиреоз у взрослых — микседема.",difficulty:"medium",tags:["щитовидная железа","патология"]},{id:"endocrine-glands-031",topicId:"endocrine-glands",question:"Какой признак характерен для микседемы?",options:["Экзофтальм","Брадикардия","Тахикардия","Похудение"],correctIndex:1,explanation:"Микседема проявляется отёчностью, увеличением массы тела, сонливостью, сухой кожей и брадикардией.",difficulty:"medium",tags:["щитовидная железа","патология"]},{id:"endocrine-glands-032",topicId:"endocrine-glands",question:"Что указано в лекции как частая причина гипотиреоза?",options:["Избыток соматотропного гормона","Избыток кальция","Дефицит витамина D","Дефицит йода"],correctIndex:3,explanation:"Частая причина недостатка гормонов щитовидной железы — дефицит йода.",difficulty:"easy",tags:["щитовидная железа","патология"]},{id:"endocrine-glands-033",topicId:"endocrine-glands",question:"Как ещё называют болезнь Грейвса?",options:["Базедова болезнь","Феохромоцитома","Микседема","Болезнь Аддисона"],correctIndex:0,explanation:"Болезнь Грейвса (Базедова болезнь) — проявление гипертиреоза.",difficulty:"medium",tags:["щитовидная железа","патология"]},{id:"endocrine-glands-034",topicId:"endocrine-glands",question:"Какой признак характерен для болезни Грейвса?",options:["Экзофтальм","Сонливость","Увеличение массы тела","Брадикардия"],correctIndex:0,explanation:"При болезни Грейвса: тахикардия, похудение, раздражительность, тремор рук, экзофтальм, повышенная потливость.",difficulty:"medium",tags:["щитовидная железа","патология"]},{id:"endocrine-glands-035",topicId:"endocrine-glands",question:"Где расположены паращитовидные железы?",options:["Над верхними полюсами почек","В верхнем средостении","В промежуточном мозге","На задней поверхности щитовидной железы"],correctIndex:3,explanation:"Паращитовидные железы расположены на задней поверхности щитовидной железы (обычно их 4).",difficulty:"medium",tags:["паращитовидные железы"]},{id:"endocrine-glands-036",topicId:"endocrine-glands",question:"Сколько паращитовидных желёз обычно бывает у человека?",options:["1","4","6","2"],correctIndex:1,explanation:"Паращитовидных желёз обычно 4.",difficulty:"medium",tags:["паращитовидные железы"]},{id:"endocrine-glands-037",topicId:"endocrine-glands",question:"Какой гормон вырабатывают паращитовидные железы?",options:["Кальцитонин","Мелатонин","Тироксин","Паратгормон (ПТГ)"],correctIndex:3,explanation:"Гормон паращитовидных желёз — паратгормон (ПТГ).",difficulty:"easy",tags:["паращитовидные железы","гормоны"]},{id:"endocrine-glands-038",topicId:"endocrine-glands",question:"Как паратгормон влияет на уровень кальция в крови?",options:["Снижает его","Повышает его","Не влияет на кальций","Повышает только уровень фосфора"],correctIndex:1,explanation:"Паратгормон повышает уровень кальция в крови, усиливает резорбцию костной ткани, всасывание кальция в кишечнике и реабсорбцию в почках.",difficulty:"medium",tags:["паращитовидные железы","гормоны"]},{id:"endocrine-glands-039",topicId:"endocrine-glands",question:"Где расположены надпочечники?",options:["В полости малого таза","У ворот печени","Над верхними полюсами почек","На задней поверхности щитовидной железы"],correctIndex:2,explanation:"Надпочечники — парные железы, расположенные над верхними полюсами почек.",difficulty:"easy",tags:["надпочечники"]},{id:"endocrine-glands-040",topicId:"endocrine-glands",question:"Какие гормоны вырабатывает мозговой слой надпочечников?",options:["Тироксин и кальцитонин","Кортизол и альдостерон","Андрогены и эстрогены","Адреналин и норадреналин"],correctIndex:3,explanation:"Мозговой слой надпочечников вырабатывает адреналин и норадреналин, обеспечивающие реакцию «бей или беги».",difficulty:"medium",tags:["надпочечники","гормоны"]},{id:"endocrine-glands-041",topicId:"endocrine-glands",question:"Какой гормон коркового слоя надпочечников регулирует водно-солевой баланс?",options:["Вазопрессин","Адреналин","Кортизол","Альдостерон"],correctIndex:3,explanation:"Минералокортикоид альдостерон коркового слоя надпочечников регулирует водно-солевой баланс.",difficulty:"medium",tags:["надпочечники","гормоны"]},{id:"endocrine-glands-042",topicId:"endocrine-glands",question:"К какой группе гормонов относится кортизол?",options:["Тиреоидные гормоны","Глюкокортикоиды","Катехоламины","Минералокортикоиды"],correctIndex:1,explanation:"Кортизол — глюкокортикоид коркового слоя надпочечников, регулирует обмен веществ и реакцию на стресс.",difficulty:"medium",tags:["надпочечники","гормоны"]},{id:"endocrine-glands-043",topicId:"endocrine-glands",question:"Недостаток каких гормонов вызывает болезнь Аддисона?",options:["Адреналина и норадреналина","Инсулина и глюкагона","Тироксина и трийодтиронина","Кортизола и альдостерона"],correctIndex:3,explanation:"Болезнь Аддисона — недостаток кортизола и альдостерона.",difficulty:"medium",tags:["надпочечники","патология"]},{id:"endocrine-glands-044",topicId:"endocrine-glands",question:"Какой признак характерен для болезни Аддисона?",options:["Бронзовая пигментация кожи","Приступы гипертонии","Увеличение нижней челюсти","Экзофтальм"],correctIndex:0,explanation:"Болезнь Аддисона: слабость, гипотония, бронзовая пигментация кожи, потеря веса, гипогликемия.",difficulty:"medium",tags:["надпочечники","патология"]},{id:"endocrine-glands-045",topicId:"endocrine-glands",question:"Избыток каких гормонов наблюдается при феохромоцитоме?",options:["Паратгормона","Пролактина","Кортизола и альдостерона","Адреналина и норадреналина"],correctIndex:3,explanation:"Феохромоцитома — избыток адреналина/норадреналина: приступы гипертонии, тахикардия, потливость, страх, тревога.",difficulty:"hard",tags:["надпочечники","патология"]},{id:"endocrine-glands-046",topicId:"endocrine-glands",question:"Где расположен тимус (вилочковая железа)?",options:["В верхнем средостении за грудиной","В промежуточном мозге","Над почками","На передней поверхности шеи"],correctIndex:0,explanation:"Тимус расположен в верхнем средостении за грудиной.",difficulty:"medium",tags:["тимус"]},{id:"endocrine-glands-047",topicId:"endocrine-glands",question:"Что происходит с тимусом после периода полового созревания?",options:["Он постепенно замещается жировой тканью","Он активно растёт","Он превращается в лимфатический узел","Он начинает вырабатывать инсулин"],correctIndex:0,explanation:"Тимус активно растёт до периода полового созревания, затем постепенно замещается жировой тканью.",difficulty:"medium",tags:["тимус"]},{id:"endocrine-glands-048",topicId:"endocrine-glands",question:"Какова основная функция тимуса?",options:["Выработка адреналина","Регуляция уровня кальция","Выработка мелатонина","Созревание Т-лимфоцитов и формирование иммунитета"],correctIndex:3,explanation:"Функции тимуса — созревание Т-лимфоцитов и формирование иммунитета.",difficulty:"easy",tags:["тимус","функции"]},{id:"endocrine-glands-049",topicId:"endocrine-glands",question:"К чему приводит гипофункция тимуса?",options:["К иммунодефициту с частыми инфекциями","К бронзовой пигментации кожи","К гигантизму","К гипертиреозу"],correctIndex:0,explanation:"Гипофункция тимуса приводит к иммунодефициту — частым инфекциям.",difficulty:"medium",tags:["тимус","патология"]}];export{n as default};
